use std::io::{Read,Write};use spore_core::{cell_fresh_sweep_registration_v1::{Slot,Endpoint},cell_sweep_pending_update_v1::{self as pending,X87Admission}};
fn main()->Result<(),Box<dyn std::error::Error>>{let mut input=Vec::new();std::io::stdin().read_to_end(&mut input)?;if input.len()!=96{return Err("expected 4 cases".into())}let mut out=Vec::new();for row in input.chunks_exact(24){let u16at=|p:usize|u16::from_le_bytes(row[p..p+2].try_into().unwrap());let u32at=|p:usize|u32::from_le_bytes(row[p..p+4].try_into().unwrap());let slot=Slot{actor:0x12345678,tag:0x87654321,endpoint_links:std::array::from_fn(|i|0x8000|u16at(i*2))};let mut axes:[Vec<Endpoint>;2]=std::array::from_fn(|axis|(0..4).map(|i|Endpoint{opening:(axis*16+i) as u16,slot:0,value_bits:0x3e800000+axis as u32*0x10000+i as u32}).collect());pending::update(&slot,&mut axes,[u32at(8),u32at(12)],[u32at(16),u32at(20)],X87Admission::Default027f).map_err(|e|format!("{e:?}"))?;out.extend(slot.actor.to_le_bytes());out.extend(slot.tag.to_le_bytes());for v in slot.endpoint_links{out.extend(v.to_le_bytes())}for axis in axes{for e in axis{out.extend(e.opening.to_le_bytes());out.extend(e.slot.to_le_bytes());out.extend(e.value_bits.to_le_bytes())}}}std::io::stdout().write_all(&out)?;Ok(())}
